-- WhiteCap Full Sync — Fixed date parsing
-- 528 tasks | 119 projects | Safe to rerun

DROP TABLE IF EXISTS _wc_stage;
CREATE TEMP TABLE _wc_stage (
  project_name TEXT, scope TEXT, title TEXT, status TEXT,
  detailer TEXT, checker TEXT, rec_date DATE, csd DATE,
  det_weight NUMERIC, color TEXT);


-- Create missing projects
SELECT DISTINCT s.project_name,'White Cap',s.color,'','{}'::text[],'White Cap'
FROM _wc_stage s WHERE NOT EXISTS (
  SELECT 1 FROM projects p WHERE LOWER(TRIM(p.name))=LOWER(TRIM(s.project_name))
    AND LOWER(p.client) LIKE '%white%');

-- Insert new tasks
SELECT p.id,s.title,'White Cap',s.status,'Medium',s.detailer,s.detailer,s.checker,
  s.scope,s.rec_date,s.csd,s.det_weight,'{}'::text[],'{}'::text[]
FROM _wc_stage s
JOIN projects p ON LOWER(TRIM(p.name))=LOWER(TRIM(s.project_name)) AND LOWER(p.client) LIKE '%white%'
WHERE NOT EXISTS (SELECT 1 FROM tasks t WHERE t.project_id=p.id AND LOWER(TRIM(t.title))=LOWER(TRIM(s.title)));

-- Update existing tasks
UPDATE tasks t SET
  status=s.status, assignee=s.detailer, detailer=s.detailer, checker=s.checker,
  scope=s.scope, due_date=s.rec_date, client_sub_date=s.csd, det_weight=s.det_weight
FROM _wc_stage s
JOIN projects p ON LOWER(TRIM(p.name))=LOWER(TRIM(s.project_name)) AND LOWER(p.client) LIKE '%white%'
WHERE t.project_id=p.id AND LOWER(TRIM(t.title))=LOWER(TRIM(s.title));

-- Summary
SELECT COUNT(*) FILTER(WHERE LOWER(p.client) LIKE '%white%') total,
  COUNT(*) FILTER(WHERE LOWER(p.client) LIKE '%white%' AND t.status='Completed') completed,
  COUNT(*) FILTER(WHERE LOWER(p.client) LIKE '%white%' AND t.status='In Progress') in_progress,
  COUNT(*) FILTER(WHERE LOWER(p.client) LIKE '%white%' AND t.status='On Hold') on_hold,
  COUNT(*) FILTER(WHERE LOWER(p.client) LIKE '%white%' AND t.status='Not Yet Started') not_started,
  COUNT(*) FILTER(WHERE LOWER(p.client) LIKE '%white%' AND t.due_date < CURRENT_DATE AND t.status!='Completed') overdue
FROM tasks t JOIN projects p ON p.id=t.project_id;

-- Overdue tasks
SELECT p.name project,t.title,t.status,t.due_date,t.detailer
FROM tasks t JOIN projects p ON p.id=t.project_id
WHERE LOWER(p.client) LIKE '%white%' AND t.due_date<CURRENT_DATE AND t.status NOT IN('Completed','On Hold')
ORDER BY t.due_date;
